  const cards = "<article id=\"entry-dgp-1386\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀκόντως</h1><div class=\"entry-meta\"><span>DGP · ordem 1386 na letra α · nº geral 1386</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adv. de mau grado; a contragosto.</p></section></article>\n<article id=\"entry-dgp-1387\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἄκοπος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 1387 na letra α · nº geral 1387</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 que não provoca fadiga; que elimina a fadiga ou a dor 2 não fatigado; infatigável 3 não cortado; não estragado; intacto. 〈ἀ-, κόπτω〉</p></section></article>\n<article id=\"entry-dgp-1388\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀκόρεστος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 1388 na letra α · nº geral 1388</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 que não ficou saciado; insaciável de, gen. 2 que não produz saciedade; interminável. 〈ἀ-, κορέννυμι〉</p></section></article>\n<article id=\"entry-dgp-1389\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀκόρετος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 1389 na letra α · nº geral 1389</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">ἀκόρεστος.</p></section></article>\n<article id=\"entry-dgp-1390\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀκορής, ής, ές</h1><div class=\"entry-meta\"><span>DGP · ordem 1390 na letra α · nº geral 1390</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">ἀκόρητος.</p></section></article>\n<article id=\"entry-dgp-1391\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀκόρητος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 1391 na letra α · nº geral 1391</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">insaciável de, gen. 〈ἀ-, κορέννυμι〉</p></section></article>\n<article id=\"entry-dgp-1392\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀκορία, ας (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1392 na letra α · nº geral 1392</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">desejo insaciável. 〈ἄκορος〉</p></section></article>\n<article id=\"entry-dgp-1393\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἄκορος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 1393 na letra α · nº geral 1393</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">insaciável. 〈ἀ-, κόρος〉</p></section></article>\n<article id=\"entry-dgp-1394\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἄκος, εος-ους (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 1394 na letra α · nº geral 1394</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">remédio contra ou para, gen.; ἄκος οὐδέν de nada serve, inf.</p></section></article>\n<article id=\"entry-dgp-1395\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀκοσμέω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 1395 na letra α · nº geral 1395</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 perturbar a ordem; agir de modo vil 2 cometer infração. 〈ἄκοσμος〉</p></section></article>\n<article id=\"entry-dgp-1396\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀκόσμητος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 1396 na letra α · nº geral 1396</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 não ordenado; não arranjado 2 não ornado; não enfeitado. 〈ἀ, κοσμέω〉</p></section></article>\n<article id=\"entry-dgp-1397\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀκοσμία, ας (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1397 na letra α · nº geral 1397</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 desordem; desregramento; confusão 2 falta de ornamento. 〈ἄκοσμος〉</p></section></article>\n<article id=\"entry-dgp-1398\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἄκοσμος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 1398 na letra α · nº geral 1398</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 desordenado; desregrado; confuso 2 que é feito sem ordem; sem beleza. 〈ἀ-, κόσμος〉</p></section></article>\n<article id=\"entry-dgp-1399\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀκόσμως</h1><div class=\"entry-meta\"><span>DGP · ordem 1399 na letra α · nº geral 1399</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adv. 1 em desordem; perturbadamente 2 sem ornamento.</p></section></article>\n<article id=\"entry-dgp-1400\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀκοστάω</h1><div class=\"entry-meta\"><span>DGP · ordem 1400 na letra α · nº geral 1400</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">e ἀκοστέω (só part. aor. ἀκοστήσας hom.) comer cevada; nutrir-se. 〈ἀκοστή〉</p></section></article>\n<article id=\"entry-dgp-1401\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀκοστή, ῆς (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1401 na letra α · nº geral 1401</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">cevada.</p></section></article>\n<article id=\"entry-dgp-1402\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀκουάζομαι</h1><div class=\"entry-meta\"><span>DGP · ordem 1402 na letra α · nº geral 1402</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 ouvir alguém, gen. 2 sentir-se convidado a, gen. 3 auscultar. 〈ἀκούω〉</p></section></article>\n<article id=\"entry-dgp-1403\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀκουέμεν, ἀκουέμεναι</h1><div class=\"entry-meta\"><span>DGP · ordem 1403 na letra α · nº geral 1403</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">inf. pres. ép. de ἀκούω.</p></section></article>\n<article id=\"entry-dgp-1404\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀκουή</h1><div class=\"entry-meta\"><span>DGP · ordem 1404 na letra α · nº geral 1404</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">ép. = ἀκοή.</p></section></article>\n<article id=\"entry-dgp-1405\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἄκουκα</h1><div class=\"entry-meta\"><span>DGP · ordem 1405 na letra α · nº geral 1405</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">dór. = ἀκήκοα.</p></section></article>\n<article id=\"entry-dgp-1406\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἄκουον</h1><div class=\"entry-meta\"><span>DGP · ordem 1406 na letra α · nº geral 1406</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">impf. poét. de ἀκούω.</p></section></article>\n<article id=\"entry-dgp-1407\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἄκουρος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 1407 na letra α · nº geral 1407</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">sem filhos. 〈ἀ-, κοῦρος〉</p></section></article>\n<article id=\"entry-dgp-1408\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἄκουσα1</h1><div class=\"entry-meta\"><span>DGP · ordem 1408 na letra α · nº geral 1408</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">fem. de ἄκων2.</p></section></article>\n<article id=\"entry-dgp-1409\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἄκουσα2</h1><div class=\"entry-meta\"><span>DGP · ordem 1409 na letra α · nº geral 1409</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">aor. poét. de ἀκούω.</p></section></article>\n<article id=\"entry-dgp-1410\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀκούσιος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 1410 na letra α · nº geral 1410</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">át. 1 contrário à vontade; forçado 2 involuntário. 〈ἀ-, ἑκούσιος〉</p></section></article>\n<article id=\"entry-dgp-1411\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀκουσίως</h1><div class=\"entry-meta\"><span>DGP · ordem 1411 na letra α · nº geral 1411</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adv. 1 involuntariamente 2 a contragosto; contra a vontade de alguém, dat.</p></section></article>\n<article id=\"entry-dgp-1412\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἄκουσμα, ατος (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 1412 na letra α · nº geral 1412</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 o que se ouve; som (palavra, música) 2 notícia; relato 3 rumor; boato 4 instrução oral. 〈ἀκούω〉</p></section></article>\n<article id=\"entry-dgp-1413\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀκουστέος, α, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 1413 na letra α · nº geral 1413</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adj. verb. de ἀκούω.</p></section></article>\n<article id=\"entry-dgp-1414\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀκουστικός, ή, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 1414 na letra α · nº geral 1414</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 próprio para fazer ouvir 2 próprio para ouvir; disposto a ouvir, gen. ♦ τὸ ἀκουστικόν 3 a faculdade de ouvir. 〈ἀκούω〉</p></section></article>\n<article id=\"entry-dgp-1415\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀκουστός, ή, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 1415 na letra α · nº geral 1415</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">audível. 〈ἀκούω〉</p></section></article>\n<article id=\"entry-dgp-1416\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀκούω</h1><div class=\"entry-meta\"><span>DGP · ordem 1416 na letra α · nº geral 1416</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(fut. ἀκούσομαι, aor. ἤκουσα, perf. ἀκήκοα, m.-q.-perf. ἠκηκόειν, át. ἠκηκόη; pas. fut. ἀκουσθήσομαι, aor. ἠκούσθην, perf. ἤκουσμαι, m.-q.-perf. ἠκούσμην) 1 ouvir alguém, gen.; algo, ac. ou gen.; de alguém, gen. ou ἀπό, ἐκ, παρά, πρός e gen. 2 ouvir falar de alguém, gen., περί e gen.; ouvir dizer que, or. conj. (ὡς, ὅτι), inter., inf., part. 3 ouvir com atenção; escutar; atender a, gen. 4 ouvir falar de si; ter reputação de, ac., predic. ou adv., às vezes inf. 1 ἄκουσα θεοῦ hom. ouvi um deus, τὰ βέλτιστ’ ἀκούειν dem. ouvir as melhores opiniões, κωκυτοῦ δ’ ἤκουσε hom. ouviu o urro, οὐδεὶς ἤκουσέ σου ταύτην τὴν φωνήν dem. ninguém ouviu de ti essa palavra 2 πατρὸς ἀκούσας hom. tendo ouvido falar de seu pai, περὶ σοῦ ἀκούσαντες πολλὰ ἀγαθά xen. tendo ouvido dizer muitas boas coisas de ti, οὐκ ἀκήκοας ὅτι ἠναγκάζετο δουλεύειν; xen. não ficaste sabendo que ele era reduzido a escravo? ἐπιθυμῶ ἀκοῦσαι τίνας ἔλεγες τὰς τέτταρας πολιτείας plat. desejo ouvir quais são as quatro formas de governo que enunciavas, καὶ σὲ τὸ πρὶν ἀκούομεν ὄλβιον εἷναι hom. e ouvimos dizer que outrora eras feliz, ὡς ἤκουσαν οὐδὲν πεπραγμένον tuc. quando souberam que nada tinha sido feito 3 λόγων ἀκουσομένους ἀφῖχθαι plat. ter vindo ouvir a discussão, Ἀναξιμάνδρου ἤκουσεν d.l. assistiu aos cursos de Anaximandro, πᾶς ὅστις ἀκούει μου τοὺς λόγους n.t. todo aquele que ouve a minha palavra 4 φήμας κακὰς ἤκουσεν οὐκ αἰτία eur. teve má reputação, sem ser culpada, κακὸς ἀκούω sóf. chamam-me de mau, κακῶς ἤκουεν dem. falavam mal dele, εὖ ἀκούειν at. ter boa reputação, ἤκουον εἷναι πρῶτοι her. tinham a reputação de ser os primeiros.</p></section></article>\n<article id=\"entry-dgp-1417\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἄκρα, ας (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1417 na letra α · nº geral 1417</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">cf. ἄκρος.</p></section></article>\n<article id=\"entry-dgp-1418\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀκράαντος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 1418 na letra α · nº geral 1418</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">ἄκραντος.</p></section></article>\n<article id=\"entry-dgp-1419\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Ἀκραγαντῖνος, η, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 1419 na letra α · nº geral 1419</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">de Agrigento. 〈Ἀκράγας〉</p></section></article>\n<article id=\"entry-dgp-1420\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Ἀκράγας, αντος (ὁ, ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1420 na letra α · nº geral 1420</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">Agrigento, rio e cidade da Sicília.</p></section></article>\n<article id=\"entry-dgp-1421\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀκραγής, ής, ές</h1><div class=\"entry-meta\"><span>DGP · ordem 1421 na letra α · nº geral 1421</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">duv. que não grita ou que grita muito forte; feroz. 〈ἀ- priv. ou intens., κράζω〉</p></section></article>\n<article id=\"entry-dgp-1422\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀκραής, ής, ές</h1><div class=\"entry-meta\"><span>DGP · ordem 1422 na letra α · nº geral 1422</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">que sopra forte. 〈ἄκρος, ἄημι〉</p></section></article>\n<article id=\"entry-dgp-1423\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀκραῖος, α, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 1423 na letra α · nº geral 1423</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">que está na extremidade ou na parte de cima; que habita as alturas. 〈ἄκρος〉</p></section></article>\n<article id=\"entry-dgp-1424\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀκραιφνής, ής, ές</h1><div class=\"entry-meta\"><span>DGP · ordem 1424 na letra α · nº geral 1424</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 não misturado; puro 2 intacto 3 isento de, gen. 〈ἀκέραιος, φαίνω〉</p></section></article>\n<article id=\"entry-dgp-1425\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἄκραντος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 1425 na letra α · nº geral 1425</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 que não se cumpre; que não se realiza; vão 2 rar. que não realiza nada ♦ ἄκραντα adv. 3 em vão. 〈ἀ-, κραίνω〉</p></section></article>\n<article id=\"entry-dgp-1426\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀκρασία, ας (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1426 na letra α · nº geral 1426</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 excesso; falta de medida; intemperança 2 intempérie. 〈ἀκρατής〉</p></section></article>\n<article id=\"entry-dgp-1427\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀκράτεια, ας (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1427 na letra α · nº geral 1427</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 falta de força; fraqueza 2 falta de autodomínio; intemperança. 〈ἀκρατής〉</p></section></article>\n<article id=\"entry-dgp-1428\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀκρατεύομαι</h1><div class=\"entry-meta\"><span>DGP · ordem 1428 na letra α · nº geral 1428</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">ser intemperante 〈ἀκρατής〉</p></section></article>\n<article id=\"entry-dgp-1429\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀκρατευτικός, ή, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 1429 na letra α · nº geral 1429</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">relativo à intemperança. 〈ἀκρα­τεύομαι〉</p></section></article>\n<article id=\"entry-dgp-1430\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀκρατής, ής, ές</h1><div class=\"entry-meta\"><span>DGP · ordem 1430 na letra α · nº geral 1430</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 sem força; débil 2 incapaz de manter o controle de, gen.: ἀ. χειρῶν, γλώσσης sem o controle das mãos, da língua 3 incapaz de moderar-se no uso de; dominado pelo amor de, gen., πρός ou περί e ac., inf.: ἀ. οἴνου ou πρὸς τὸν οἷνον imoderado no vinho, ἀ. κέρδους insaciável de lucro, ἀ. εἴργεσθαί τινος, incapaz de abster-se de alguma coisa 4 que não é senhor de si; incapaz de moderar-se: στόμα ἀ. língua desregrada, ἀ. δαπάνη gasto imoderado. 〈ἀ-, κράτος〉</p></section></article>\n<article id=\"entry-dgp-1431\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀκρατοποσία, ας (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1431 na letra α · nº geral 1431</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">ação de beber vinho puro. 〈ἀκρα­τοπότης〉</p></section></article>\n<article id=\"entry-dgp-1432\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀκρατοπότης, ου (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1432 na letra α · nº geral 1432</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">bebedor de vinho puro. 〈ἄκρατος, πίνω〉</p></section></article>\n<article id=\"entry-dgp-1433\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἄκρατος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 1433 na letra α · nº geral 1433</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 não misturado; puro: ἄ. οἷνος vinho puro, ἄκρατα σώματα plat. corpos simples 2 puro; absoluto; perfeito: νοῦς ἄ. xen. puro pensamento, ἄ. ἐλευθερία plat. absoluta liberdade 3 completo; excessivo; violento: ἄ. ψεῦδος plat. pura mentira, ἄκρατος ὀργήν ésql. desmedido em sua cólera ♦ ὁ ἄκρατος, τὸ ἄκρατον 4 vinho puro. 〈ἀ-, κεράννυμι〉</p></section></article>\n<article id=\"entry-dgp-1434\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀκράτωρ, ορος (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1434 na letra α · nº geral 1434</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 sem força; impotente 2 que não tem controle sobre; que não é senhor de, gen. 〈ἀ-, κράτος〉</p></section></article>\n<article id=\"entry-dgp-1435\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀκράτως</h1><div class=\"entry-meta\"><span>DGP · ordem 1435 na letra α · nº geral 1435</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adv. sem mistura; absolutamente; inteiramente.</p></section></article>\n<article id=\"entry-dgp-1436\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀκραχολέω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 1436 na letra α · nº geral 1436</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(só part. pres.) irritar-se. 〈ἀκράχολος〉</p></section></article>\n<article id=\"entry-dgp-1437\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀκραχολία, ας (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1437 na letra α · nº geral 1437</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">irritação. 〈ἀκράχολος〉</p></section></article>\n<article id=\"entry-dgp-1438\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀκράχολος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 1438 na letra α · nº geral 1438</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 colérico; irascível 2 pálido. 〈ἄκρος, χολή〉</p></section></article>\n<article id=\"entry-dgp-1439\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀκρεμών, όνος (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1439 na letra α · nº geral 1439</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">a ponta do ramo. 〈ἄκρος〉</p></section></article>\n<article id=\"entry-dgp-1440\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἄκρη</h1><div class=\"entry-meta\"><span>DGP · ordem 1440 na letra α · nº geral 1440</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">jôn. = ἄκρα.</p></section></article>\n<article id=\"entry-dgp-1441\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀκρητοποσίη, ἀκρητοπότης, ἄκρητος</h1><div class=\"entry-meta\"><span>DGP · ordem 1441 na letra α · nº geral 1441</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">jôn. = ἀκρατο­ποσία, ἀκρατοπότης, ἄκρατος.</p></section></article>\n<article id=\"entry-dgp-1442\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀκρίβεια, ας (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1442 na letra α · nº geral 1442</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 exatidão; precisão 2 rigor; severidade; δι᾽ ἀκριβείας, εἰς ou πρὸς ἀκρίβειαν, ἐν ἀκριβείᾳ com todo o rigor; com exatidão 3 economia rígida; parcimônia. 〈ἀκριβής〉</p></section></article>\n<article id=\"entry-dgp-1443\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀκριβής, ής, ές</h1><div class=\"entry-meta\"><span>DGP · ordem 1443 na letra α · nº geral 1443</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 preciso; exato: ἀ. λόγος plat. discurso exato, verdadeiro, σημεῖον ἀ. tuc. sinal preciso 2 cuidadoso; escrupuloso; severo: ἀ. νομοθέτης plat. legislador competente 3 que se adapta bem; perfeito: θώραξ ἀ. xen. couraça que se ajusta bem, ἀ. δίαιτα hipócr. regime bem regrado 4 parcimonioso ♦ ἀκριβές ou ἐπ’ ἀκριβές, εἰς τὸ ἀκριβές adv. 5 com exatidão; com precisão ♦ τὸ ἀκριβές 6 verdade 7 rigor absoluto.</p></section></article>\n<article id=\"entry-dgp-1444\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀκριβολογέομαι-οῦμαι</h1><div class=\"entry-meta\"><span>DGP · ordem 1444 na letra α · nº geral 1444</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 apreciar com rigor; pesquisar minuciosamente, περί e gen. 2 ser exato; ser preciso.</p></section></article>\n<article id=\"entry-dgp-1445\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀκριβολογητέον</h1><div class=\"entry-meta\"><span>DGP · ordem 1445 na letra α · nº geral 1445</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adj. verb. de ἀκριβολογέομαι.</p></section></article>\n<article id=\"entry-dgp-1446\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀκριβολογία, ας (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1446 na letra α · nº geral 1446</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">exatidão; precisão; rigor. 〈ἀκριβής, λέγω〉</p></section></article>\n<article id=\"entry-dgp-1447\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀκριβόω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 1447 na letra α · nº geral 1447</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(fut. ἀκριβώσω, aor. ἠκρίβωτα, perf. ἠκρίβωκα) 1 ser exato; ser preciso 2 tornar exato ou perfeito; fazer com o maior cuidado, ac. 3 pesquisar com rigor; averiguar; verificar a exatidão de, ac. 4 descrever com cuidado ♦ pas. 5 perf. ser perfeito. 〈ἀκριβής〉</p></section></article>\n<article id=\"entry-dgp-1448\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀκριβῶς</h1><div class=\"entry-meta\"><span>DGP · ordem 1448 na letra α · nº geral 1448</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adv. com exatidão; rigorosamente.</p></section></article>\n<article id=\"entry-dgp-1449\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀκρίς, ίδος (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1449 na letra α · nº geral 1449</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">gafanhoto.</p></section></article>\n<article id=\"entry-dgp-1450\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἄκρις, ιος (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1450 na letra α · nº geral 1450</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 pico de montanha 2 região montanhosa. 〈ἄκρος〉</p></section></article>\n<article id=\"entry-dgp-1451\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀκρισία, ας (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1451 na letra α · nº geral 1451</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 falta de discernimento; mau julgamento 2 falta de critério; confusão. 〈ἄκριτος〉</p></section></article>\n<article id=\"entry-dgp-1452\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Ἀκρίσιος, ου (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1452 na letra α · nº geral 1452</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">Acrísio, pai de Dânae.</p></section></article>\n<article id=\"entry-dgp-1453\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Ἀκρισιώνη, ης (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1453 na letra α · nº geral 1453</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">filha de Acrísio (Dânae).</p></section></article>\n<article id=\"entry-dgp-1454\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀκριτόμυθος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 1454 na letra α · nº geral 1454</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">de palavras confusas; de sentido obscuro ou incompreensível; confuso. 〈ἄκριτος, μῦθος〉</p></section></article>\n<article id=\"entry-dgp-1455\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἄκριτος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 1455 na letra α · nº geral 1455</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 confuso; indistinto: ἄκριτα πόλλ’ ἀγορεύειν hom. proferir muitas palavras confusas, θύμβος ἄ. hom. túmulo indiferenciado, comum 2 não decidido; indeciso; incessante: ἄκριτα νείκεα hom. querelas não decididas, intermináveis 3 não submetido a julgamento: ἄκριτον ἐκβαλεῖς με γῆς eur. tu me expulsarás sem julgamento desta terra, πρύτανις ἄ. ésqn. chefe imune a julgamento 4 sem discernimento; sem juízo; irreflexivo: θόλμα ἄ. pol. audácia impensada, ὕπνος ἄ. a.p. sono despreocupado 5 sem decidir-se: ἀποπλεόντων ἐς τὴν ἑαυτῶν ἀκρίτων her. navegando de volta [os gregos] para sua terra sem tomar decisão. 〈ἀ-, κρίνω〉</p></section></article>\n<article id=\"entry-dgp-1456\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀκριτόφυλλος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 1456 na letra α · nº geral 1456</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">de folhagem espessa. 〈ἄκριτος, φῦλλον〉</p></section></article>\n<article id=\"entry-dgp-1457\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀκριτόφυρτος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 1457 na letra α · nº geral 1457</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">misturado sem discernimento; em total confusão. 〈ἄκριτος, φύρω〉</p></section></article>\n<article id=\"entry-dgp-1458\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀκρίτως</h1><div class=\"entry-meta\"><span>DGP · ordem 1458 na letra α · nº geral 1458</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adv. 1 de modo indeciso 2 confusamente 3 sem discernimento.</p></section></article>\n<article id=\"entry-dgp-1459\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀκρόαμα, ατος (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 1459 na letra α · nº geral 1459</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 texto poético que se ouve (recitação, canto, representação) 2 pl. aqueles que dizem um texto poético (declamadores, cantores, atores). 〈ἀκροάομαι〉</p></section></article>\n<article id=\"entry-dgp-1460\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀκροαματικός, ή, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 1460 na letra α · nº geral 1460</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 que diz respeito à audição: ἀκροαματικαὶ διδασκαλίαι ensinamentos transmitidos oralmente aos ouvintes 2 capaz de ouvir. 〈ἀκρόαμα〉</p></section></article>\n<article id=\"entry-dgp-1461\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀκροάομαι-οῦμαι</h1><div class=\"entry-meta\"><span>DGP · ordem 1461 na letra α · nº geral 1461</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(fut. ἀκροάσομαι, aor. ἠκροασάμην, perf. ἠκρόαμαι) 1 ouvir com atenção algo, ac. ou gen.; alguém, gen. 2 obedecer a alguém, gen. 3 ser ouvinte; ser discípulo.</p></section></article>\n<article id=\"entry-dgp-1462\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀκρόασις, εως (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1462 na letra α · nº geral 1462</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 ação de escutar; atenção a, gen. 2 obe­diência a, gen. 3 audição; leitura pública de textos literários. 〈ἀκροάομαι〉</p></section></article>\n<article id=\"entry-dgp-1463\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀκροατήριον, ου (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 1463 na letra α · nº geral 1463</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">tard. sala de audiências; auditório. 〈ἀκροάομαι〉</p></section></article>\n<article id=\"entry-dgp-1464\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀκροατής, οῦ (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1464 na letra α · nº geral 1464</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 que ouve com atenção; ouvinte; discípulo 2 que lê o texto em voz alta; leitor. 〈ἀκροάομαι〉</p></section></article>\n<article id=\"entry-dgp-1465\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀκροβατέω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 1465 na letra α · nº geral 1465</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(só pres.) tard. 1 andar na ponta dos pés 2 andar de cabeça erguida; ser altivo 3 subir com esforço. 〈ἄκρος, βαίνω〉</p></section></article>\n<article id=\"entry-dgp-1466\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀκροβολίζω,</h1><div class=\"entry-meta\"><span>DGP · ordem 1466 na letra α · nº geral 1466</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">ger. méd. ἀκροβολίζομαι (aor. ἠκροβο­λισάμην) 1 lançar de longe (projetil) 2 participar de escaramuça. 〈ἀκρόβολος〉</p></section></article>\n<article id=\"entry-dgp-1467\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀκροβόλισις, εως (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1467 na letra α · nº geral 1467</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">escaramuça; enfrentamento à distância. 〈ἀκροβολίζομαι〉</p></section></article>\n<article id=\"entry-dgp-1468\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀκροβολισμός, οῦ (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1468 na letra α · nº geral 1468</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">ἀκροβόλισις.</p></section></article>\n<article id=\"entry-dgp-1469\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀκροβολιστής, οῦ (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1469 na letra α · nº geral 1469</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">aquele que lança de longe; atirador.</p></section></article>\n<article id=\"entry-dgp-1470\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀκρόβολος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 1470 na letra α · nº geral 1470</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">golpeado de longe. 〈ἄκρος, βάλλω〉</p></section></article>\n<article id=\"entry-dgp-1471\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀκροβυστία, ας (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1471 na letra α · nº geral 1471</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">bíbl. 1 prepúcio; ἀκροβυστίαν ἔχω ter prepúcio, i.e., ser um gentio, um não-judeu 2 incircuncisão 3 o conjunto dos não circuncidados, i.e., os gentios. 〈ἀκρόβυστος〉</p></section></article>\n<article id=\"entry-dgp-1472\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀκρόβυστος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 1472 na letra α · nº geral 1472</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">tard. incircuncidado.</p></section></article>\n<article id=\"entry-dgp-1473\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀκρογωνιαῖος, α, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 1473 na letra α · nº geral 1473</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">bíbl. angular. 〈ἀκρος, γωνία〉</p></section></article>\n<article id=\"entry-dgp-1474\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀκρόδρυον, ου (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 1474 na letra α · nº geral 1474</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 fruto 2 fruto de casca dura 3 a árvore que produz tais frutos. 〈ἄκρος, δρῦς〉</p></section></article>\n<article id=\"entry-dgp-1475\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀκροθίνιον, ου (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 1475 na letra α · nº geral 1475</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 o que está no alto da pilha, i.e., primícias 2 o que há de melhor, com gen. partit. 〈ἄκρος, θίς〉</p></section></article>\n<article id=\"entry-dgp-1476\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀκροθώραξ, ακος (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1476 na letra α · nº geral 1476</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">meio bêbado.</p></section></article>\n<article id=\"entry-dgp-1477\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀκροκελαινιάω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 1477 na letra α · nº geral 1477</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(part. pres. ép. ἀκροκελαινιόων) tornar-se escuro na superfície. 〈ἄκρος, κελαινός〉</p></section></article>\n<article id=\"entry-dgp-1478\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀκροκνεφής, ής, ές</h1><div class=\"entry-meta\"><span>DGP · ordem 1478 na letra α · nº geral 1478</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">madrugador; de madrugada. 〈ἄκρος, κνέφας〉</p></section></article>\n<article id=\"entry-dgp-1479\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀκρόκομος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 1479 na letra α · nº geral 1479</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 que prende ou que tem os cabelos no alto da cabeça 2 que tem pêlos na extremidade 3 cheio de folhas na extremidade; que tem copa alta. 〈ἄκρος, κόμη〉</p></section></article>\n<article id=\"entry-dgp-1480\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Ἀκροκόρινθος, ου (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1480 na letra α · nº geral 1480</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">Acrocorinto, cidadela de Corinto.</p></section></article>\n<article id=\"entry-dgp-1481\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀκρόλοφος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 1481 na letra α · nº geral 1481</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">poét. 1 de pico elevado ♦ ὁ ἀκρόλοφος 2 pico; cimo de montanha. 〈ἄκρος, λόφος〉</p></section></article>\n<article id=\"entry-dgp-1482\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀκρομανής, ής, ές</h1><div class=\"entry-meta\"><span>DGP · ordem 1482 na letra α · nº geral 1482</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">próximo da loucura; meio louco. 〈ἄκρος, μαίνομαι〉</p></section></article>\n<article id=\"entry-dgp-1483\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἄκρον, ου (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 1483 na letra α · nº geral 1483</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">cf. ἄκρος.</p></section></article>\n<article id=\"entry-dgp-1484\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀκροπενθής, ής, ές</h1><div class=\"entry-meta\"><span>DGP · ordem 1484 na letra α · nº geral 1484</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">que está no auge da aflição. 〈ἄκρος, πένθος〉</p></section></article>\n<article id=\"entry-dgp-1485\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀκροποδητί</h1><div class=\"entry-meta\"><span>DGP · ordem 1485 na letra α · nº geral 1485</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adv. na ponta dos pés. 〈ἄκρος, ποῦς〉</p></section></article>\n";
